import type { InstallProfile } from "../types.js";

export type InstallChannel = "cli" | "native-plugin";

export interface InstallChannelRecord {
  readonly schemaVersion: 1;
  readonly channel: InstallChannel;
  readonly profile: InstallProfile;
  readonly updatedAt: string;
  readonly note: string;
}

export const installChannelPath = ".mstack/install-channel.json";

export const mstackGeneratedMarker =
  "<!-- Generated by mstack from Misbah's Build Like This workflow. Regenerate instead of editing. -->";

export function createInstallChannelRecord(
  channel: InstallChannel,
  profile: InstallProfile,
  updatedAt = new Date().toISOString(),
): InstallChannelRecord {
  return {
    schemaVersion: 1,
    channel,
    profile,
    updatedAt,
    note:
      channel === "cli"
        ? "Installed by mstack ai setup. Do not also install the same skills from a native marketplace or skills.sh into this repository."
        : "Installed from a native marketplace or skills.sh layout. Prefer that channel for updates; skip mstack ai setup skill writes unless migrating with --force.",
  };
}

export interface DuplicateSkillFinding {
  readonly code: "channel-conflict" | "untracked-mstack-skill" | "skills-sh-lock";
  readonly level: "warning" | "error";
  readonly path: string;
  readonly message: string;
}
